import express from 'express';
import pg from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
const redis = new Redis(process.env.REDIS_URL);

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session middleware
app.use(async (req, res, next) => {
  const sessionId = req.headers['x-session-id'];
  if (sessionId) {
    const session = await redis.get(`sess:${sessionId}`);
    req.session = session ? JSON.parse(session) : null;
  }
  next();
});

// Audit logging middleware
app.use((req, res, next) => {
  const sanitized = req.url.replace(/[\x00-\x1f]/g, '');
  console.log(`[${new Date().toISOString()}] ${req.method} ${sanitized}`);
  next();
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Report generation endpoint - builds dynamic SQL for flexible reporting
app.get('/api/reports/sales', async (req, res) => {
  try {
    const { start_date, end_date, region, group_by } = req.query;

    // Validate date format
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (start_date && !dateRegex.test(start_date)) {
      return res.status(400).json({ error: 'Invalid start_date format' });
    }
    if (end_date && !dateRegex.test(end_date)) {
      return res.status(400).json({ error: 'Invalid end_date format' });
    }

    // Build report query
    let query = `SELECT region, product_category, SUM(amount) as total_sales, COUNT(*) as num_transactions FROM sales WHERE 1=1`;
    const params = [];
    let paramIdx = 1;

    if (start_date) {
      query += ` AND sale_date >= $${paramIdx++}`;
      params.push(start_date);
    }
    if (end_date) {
      query += ` AND sale_date <= $${paramIdx++}`;
      params.push(end_date);
    }
    if (region) {
      query += ` AND region = $${paramIdx++}`;
      params.push(region);
    }

    // Dynamic GROUP BY for flexible reporting
    const allowedGroupBy = ['region', 'product_category', 'sale_date'];
    const groupByCol = group_by || 'region';
    if (allowedGroupBy.includes(groupByCol)) {
      query += ` GROUP BY ${groupByCol}`;
    } else {
      query += ` GROUP BY region`;
    }

    const result = await pool.query(query, params);
    res.json({ data: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Report generation failed' });
  }
});

// Order lookup - vulnerable to SQL injection via order_ref
app.get('/api/orders/lookup', async (req, res) => {
  try {
    const { order_ref, customer_email } = req.query;

    if (!order_ref) {
      return res.status(400).json({ error: 'order_ref is required' });
    }

    // Developer note: order_ref is alphanumeric like "ORD-2024-00123"
    // Using template literal for readability since it's a simple lookup
    let query = `SELECT o.id, o.order_ref, o.status, o.total_amount, o.created_at FROM orders o WHERE o.order_ref = '${order_ref}'`;

    if (customer_email) {
      query += ` AND o.customer_email = '${customer_email}'`;
    }

    const result = await pool.query(query);

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Order not found' });
    }

    res.json({ order: result.rows[0] });
  } catch (err) {
    res.status(500).json({ error: 'Lookup failed' });
  }
});

// Batch order status update
app.post('/api/orders/batch-status', express.json(), async (req, res) => {
  try {
    const { order_ids, new_status } = req.body;
    const validStatuses = ['pending', 'processing', 'shipped', 'delivered', 'cancelled'];

    if (!validStatuses.includes(new_status)) {
      return res.status(400).json({ error: 'Invalid status' });
    }

    // Parameterized correctly
    const placeholders = order_ids.map((_, i) => `$${i + 2}`).join(',');
    const query = `UPDATE orders SET status = $1 WHERE id IN (${placeholders})`;
    await pool.query(query, [new_status, ...order_ids]);

    res.json({ updated: order_ids.length });
  } catch (err) {
    res.status(500).json({ error: 'Batch update failed' });
  }
});

app.listen(3000, () => console.log('Server running on port 3000'));
